import heapq

def heuristic(a, b):
    """Computes the Manhattan distance heuristic between two grid cells."""
    # Convert coordinates to integer indices if necessary
    ax, ay = int(a[0]), int(a[1])
    bx, by = int(b[0]), int(b[1])

    return abs(ax - bx) + abs(ay - by)

def astar(graph, start, goal):
    # Formulate the open list: This contains the nodes to be considered
    # The actual list is just a wrapper around heapq, implementing it lazily to avoid a dependency on heapq
