        return [(node, cost, index) for index, (node, cost, index) in enumerate(tree)]

    tree = [(0.0, start, -1)] + [(float('inf'), None, current) for current in graph.keys()]
    heapq.heapify(tree)

    # Mark the starting node as visited
    visited = set()

    # Initialize the path from start to goal
    path = {start: None}
    cost = {start: 0}
    current_cost = 0
    parent = {start: None}

    while tree:
        # Get the first node in the tree (with the lowest cost)
        rawcost, current, parent = heapq.heappop(tree)
        current_node = current

        # Check if the current node is the goal
        if current_node == goal:
            return backtrack(path, visited, current_node), current_cost

        # Mark the current node as visited
        visited.add(current_node)

        # Generate successors; recursively run A*
        for neighbor in graph[current_node]:
            new_cost = cost[current_node] + graph[current_node][neighbor]
            if new_cost < cost.get(neighbor, float('inf')):
