import heapq

class Graph:
    def __init__(self):
        self.nodes = set()
        self.edges = {}

    def add_node(self, u):
        assert u not in self.nodes, "already has node"
        self.nodes.add(u)

    def add_edge(self, u, v, weight):
        if u not in self.edges:
            self.edges[u] = []
        if v not in self.edges:
            self.edges[v] = []
        self.edges[u].append(v)
        self.edges[v].append(u)  # Directed graphs

class Dijkstra:
    def __init__(self, graph):
        self.graph = graph
        self.distances = {}
        self.prev = {}

    # Initialize all nodes with infinite distances (or very large)
    def initialize_distances(self, source):
        self.distances = { node: float('infinity') for node in self.graph.nodes }

    # Function to relax edge (relax means reducing the edge's "dist" to a smaller one).
    def relax(self, source, to_node, weight):
        if weight < self.distances[to_node]:
            self.distances[to_node] = self.distances[source] + weight 
            # Update the previous node too in case you want to trace the path
            self.prev[to_node] = source

    # Dijkstra's algorithm
    def shortest_path(self, source):
        self.initialize_distances(source)
        Q = []
        for node in self.graph.nodes:
            heapq.heappush(Q, (self.distances[node], node))

        while Q:
            distance, current = heapq.heappop(Q)
            self.graph.nodes.discard(current)

            for to_node in self.graph.edges[current]:
                self.relax(current, to_node, 1)  # Assuming the weight is 1 for all nodes
        return self.distances

